INSERT INTO medicamento (nome, principio_ativo) VALUES ('dipirona', 'dipirona monoidratada');

INSERT INTO bula (medicamento_id, indicacao, uso, funcionamento, nao_usar, antes_de_usar, males,armazenamento, esquecer_de_usar, superdose, apresentacao, composicao) VALUES (1, 'Analgesico para dor e antitermico para febre.', 'Tomar comprimidos de 1 g com liquido, por via oral. Adultos e adolescentes acima de 15 anos: 1/2 a 1 comprimido ate 4 vezes ao dia. O comprimido pode ser partido, com a parte nao usada guardada na embalagem por ate 6 horas. Repetir a dose se necessario, respeitando a dose maxima diaria. Nao usar por vias nao orais. Em pacientes com insuficiencia renal ou hepatica, evitar altas doses; para uso curto, nao e necessaria reducao. Pacientes idosos ou debilitados devem considerar funcao renal/hepatica prejudicada. Nao mastigar. Consultar farmaceutico ou medico se os sintomas persistirem.', 'Dipirona alivia dor e febre, com inicio de acao em 30 a 60 minutos e duracao de cerca de 4 horas.', 'Nao usar em caso de alergia a dipirona, pirazolonas ou pirazolidinas (ex.: fenazona, fenilbutazona); historico de agranulocitose com essas substancias; funcao da medula ossea comprometida ou doencas hematopoieticas; broncoespasmo ou reacoes anafilactoides (urticaria, rinite, angioedema) apos uso de analgesicos (ex.: paracetamol, ibuprofeno); porfiria hepatica aguda intermitente; deficiencia de G6PD; gravidez, amamentacao, menores de 3 meses ou com menos de 5 kg. Informar suspeita de gravidez ao medico.', 'Risco de agranulocitose (febre, dor de garganta, lesoes na boca) ou pancitopenia (mal-estar, infeccao, equimoses, sangramento, palidez); interromper o uso e consultar medico se ocorrerem. Choque anafilatico e possivel em pacientes sensiveis, especialmente com alergia atopica ou asma. Reacoes cutaneas graves (sindrome de Stevens-Johnson, Necrolise Epidermica Toxica) requerem interrupcao imediata e assistencia medica. Altas doses podem prejudicar concentracao e reacao, afetando atividades como dirigir, especialmente com alcool. Pacientes com asma analgesica, urticaria cronica, intolerancia a alcool/corantes tem maior risco de reacoes anafilaticas. Reacoes hipotensivas podem ocorrer, exigindo cautela em pacientes com hipotensao, desidratacao, febre alta ou doencas cardiacas/cerebrais. Usar com supervisao em insuficiencia renal/hepatica. Hepatite aguda foi relatada; nao reutilizar dipirona se houve lesao hepatica previa sem outra causa. Informar uso de bupropiona, efavirenz, metadona, valproato, tacrolimo ou sertralina. Evitar nos primeiros 3 meses de gravidez; no segundo trimestre, apenas com avaliacao medica; nao usar nos ultimos 3 meses. Evitar amamentacao por 48 horas apos uso. Cautela em idosos e criancas pequenas; nao recomendado para menores de 15 anos. A dipirona pode induzir enzimas metabolizadoras (CYP2B6/CYP3A4), reduzindo niveis de outros medicamentos; monitorar. Pode diminuir eficacia do valproato e aumentar toxicidade do metotrexato (evitar em idosos). Reduz efeito do acido acetilsalicilico em baixas doses para protecao cardiovascular. Pode interferir em testes laboratoriais (reacoes de Trinder). Informar uso de outros medicamentos ao medico.', 'Frequencias: muito comum (>10%), comum (1-10%), incomum (0,1-1%), rara (0,01-0,1%), muito rara (<0,01%), desconhecida. Disturbios cardiacos: Sindrome de Kounis (eventos coronarianos com reacoes alergicas). Imunologicos: Choque anafilatico ou reacoes anafilactoides, graves ou fatais, com sintomas como coceira, urticaria, falta de ar, podendo progredir para angioedema, broncoespasmo, arritmias, queda de pressao ou choque. Pele: Erupcoes fixas, raramente exantema, ou sindromes graves (Stevens-Johnson, Lyell); interromper uso se houver manchas, ulceras, febre >38°C. Sangue: Anemia aplastica, agranulocitose, pancitopenia (fatais), leucopenia, trombocitopenia, com sintomas como lesoes na mucosa, febre, sangramentos. Vasculares: Reacoes hipotensivas, raramente criticas. Renais: Insuficiencia renal aguda, nefrite intersticial, urina avermelhada. Gastrintestinais: Sangramento. Hepaticos: Hepatite, ictericia, enzimas elevadas; procurar medico se houver nausea, urina escura, coceira, dor abdominal.', 'Manter em temperatura ambiente (15-30°C), protegido de luz e umidade. Nao usar apos validade vencida. Comprimido 1 g: branco a amarelado, oblongo, biconvexo com vinco. Verificar aspecto; consultar farmaceutico se alterado. Manter fora do alcance de criancas.', 'Tomar dose esquecida assim que possivel, salvo se proximo da proxima dose; nesse caso, esperar e seguir o intervalo regular. Nao dobrar a dose. Consultar farmaceutico ou medico em caso de duvidas.', 'Sintomas: nausea, vomito, dor abdominal, insuficiencia renal, tontura, sonolencia, coma, convulsoes, queda de pressao, taquicardia, urina avermelhada. Tratamento: sem antidoto especifico; lavagem gastrica ou carvao ativado podem reduzir absorcao. Metabolito eliminado por hemodialise ou filtracao. Procurar socorro medico imediatamente, levando a bula. Ligar para 0800 722 6001.', 'Comprimidos 1 g: embalagem com 10 comprimidos. Uso oral, para adultos e adolescentes acima de 15 anos.', 'Cada comprimido contem 1 g de dipirona monoidratada. Excipientes: crospovidona, estearato de magnesio, croscarmelose sodica, dioxido de silicio, povidona, metabissulfito de sodio.')
